struct Capture {
  uint32_t commands = 0, dataFlag = 0, begins = 0, ends = 0;
  RECT rect {};
  bool rectSent = false, refuseBlob = false;
  size_t requestedBytes = 0;
  std::vector<uint64_t> fields;
  std::vector<uint8_t> storage;
  static constexpr size_t guard = 32;
} capture;
struct ClientMessage {
  uint32_t get_uid() const { return 123; }
  ClientMessage(uint32_t command, uint32_t id, uint32_t flag) {
    require(command == Commands::IDirect3DSurface9_UnlockRect && id == 7, "command or resource id changed");
    ++capture.commands; capture.dataFlag = flag;
  }
  void send_data(size_t bytes, const void* data) {
    require(!capture.rectSent && bytes == sizeof(RECT), "rectangle wire header changed");
    std::memcpy(&capture.rect, data, bytes); capture.rectSent = true;
  }
  template<class T> void send_data(T value) { capture.fields.push_back(static_cast<uint64_t>(value)); }
  uint8_t* begin_data_blob(size_t size) {
    ++capture.begins; capture.requestedBytes = size;
    if (capture.refuseBlob) { return nullptr; }
    require(size < 128u * 1024u * 1024u, "test tried to allocate an oversized payload");
    capture.storage.resize(size + 2 * Capture::guard, 0xcd);
    if (benchmarkEnabled) { QueryPerformanceCounter(&copyStart); }
    return capture.storage.data() + Capture::guard;
  }
  void end_data_blob() {
    if (benchmarkEnabled) {
      LARGE_INTEGER end {}; QueryPerformanceCounter(&end);
      copyTicks += end.QuadPart - copyStart.QuadPart;
    }
    ++capture.ends;
  }
};
size_t surfaceShadowBudget() { return 128u * 1024u * 1024u; }
struct PagefileShadow {
  unsigned releases = 0;
  unsigned transfers = 0;
  unsigned observations = 0;
  struct Transfer {
    PagefileShadow& shadow;
    explicit Transfer(PagefileShadow& value) : shadow(value) { ++shadow.transfers; }
    ~Transfer() { --shadow.transfers; }
  };
  void release(size_t budget) {
    require(budget == surfaceShadowBudget(), "shadow budget changed"); ++releases;
  }
  void observeUnlock(DWORD) { ++observations; }
};
namespace l4d2_readback {
using Digest = std::vector<uint8_t>;
struct Hasher {
  Digest bytes;
  void add(const void* data, size_t size) {
    const auto* first = static_cast<const uint8_t*>(data);
    bytes.insert(bytes.end(), first, first + size);
  }
  HRESULT finish(Digest& output) { output = bytes; return S_OK; }
};
bool enabled() { return false; }
void test(uint32_t, uint32_t, const D3DSURFACE_DESC&, PagefileShadow&) {}
}
